INSERT INTO pregunta(codigo,eje_id,enunciado,opciones,respuesta_correcta,dificultad,estrategia,explicacion,activa,oa_codigo,revisada_pedagogicamente) VALUES ('V131-D21',(SELECT id FROM eje WHERE codigo='numeros'),'Una receta pide usar 1/4 de 20 nueces. ¿Cuántas nueces necesitas?','[{"clave":"A","texto":"4","tipo_error":null},{"clave":"B","texto":"5","tipo_error":null},{"clave":"C","texto":"10","tipo_error":null},{"clave":"D","texto":"16","tipo_error":null}]'::jsonb,'B',3,'numerica','La cuarta parte de 20 es 20 ÷ 4 = 5.',TRUE,'OA8',FALSE) ON CONFLICT(codigo) DO UPDATE SET enunciado=EXCLUDED.enunciado,opciones=EXCLUDED.opciones,respuesta_correcta=EXCLUDED.respuesta_correcta,dificultad=EXCLUDED.dificultad,explicacion=EXCLUDED.explicacion,oa_codigo=EXCLUDED.oa_codigo,activa=TRUE;
