INSERT INTO pregunta(codigo,eje_id,enunciado,opciones,respuesta_correcta,dificultad,estrategia,explicacion,activa,oa_codigo,revisada_pedagogicamente) VALUES ('V131-D22',(SELECT id FROM eje WHERE codigo='numeros'),'Se colorean 2/8 de una cinta por la mañana y 3/8 por la tarde. Sin superponer partes, ¿cuánto quedó coloreado?','[{"clave":"A","texto":"5/8","tipo_error":null},{"clave":"B","texto":"5/16","tipo_error":null},{"clave":"C","texto":"1/8","tipo_error":null},{"clave":"D","texto":"6/8","tipo_error":null}]'::jsonb,'A',3,'numerica','Como las partes son octavos, 2 + 3 = 5 octavos.',TRUE,'OA9',FALSE) ON CONFLICT(codigo) DO UPDATE SET enunciado=EXCLUDED.enunciado,opciones=EXCLUDED.opciones,respuesta_correcta=EXCLUDED.respuesta_correcta,dificultad=EXCLUDED.dificultad,explicacion=EXCLUDED.explicacion,oa_codigo=EXCLUDED.oa_codigo,activa=TRUE;
