INSERT INTO pregunta(codigo,eje_id,enunciado,opciones,respuesta_correcta,dificultad,estrategia,explicacion,activa,oa_codigo,revisada_pedagogicamente) VALUES ('V131-D26',(SELECT id FROM eje WHERE codigo='patrones'),'Una máquina suma siempre 6. Si ingresas 2 sale 8, y si ingresas 3 sale 9. ¿Qué saldrá si ingresas 11?','[{"clave":"A","texto":"15","tipo_error":null},{"clave":"B","texto":"16","tipo_error":null},{"clave":"C","texto":"17","tipo_error":null},{"clave":"D","texto":"18","tipo_error":null}]'::jsonb,'C',3,'numerica','La máquina suma 6: 11 + 6 = 17.',TRUE,'OA13',FALSE) ON CONFLICT(codigo) DO UPDATE SET enunciado=EXCLUDED.enunciado,opciones=EXCLUDED.opciones,respuesta_correcta=EXCLUDED.respuesta_correcta,dificultad=EXCLUDED.dificultad,explicacion=EXCLUDED.explicacion,oa_codigo=EXCLUDED.oa_codigo,activa=TRUE;
