INSERT INTO pregunta(codigo,eje_id,enunciado,opciones,respuesta_correcta,dificultad,estrategia,explicacion,activa,oa_codigo,revisada_pedagogicamente) VALUES ('V131-D40',(SELECT id FROM eje WHERE codigo='geometria'),'En un gráfico de barras las marcas del eje vertical son 0, 5, 10, 15, 20. La barra del jueves llega a la tercera marca sobre el cero. ¿Qué cantidad representa?','[{"clave":"A","texto":"5","tipo_error":null},{"clave":"B","texto":"10","tipo_error":null},{"clave":"C","texto":"15","tipo_error":null},{"clave":"D","texto":"20","tipo_error":null}]'::jsonb,'C',3,'numerica','Las marcas sobre cero corresponden 5, 10 y 15.',TRUE,'OA27',FALSE) ON CONFLICT(codigo) DO UPDATE SET enunciado=EXCLUDED.enunciado,opciones=EXCLUDED.opciones,respuesta_correcta=EXCLUDED.respuesta_correcta,dificultad=EXCLUDED.dificultad,explicacion=EXCLUDED.explicacion,oa_codigo=EXCLUDED.oa_codigo,activa=TRUE;
